ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn = "everywhere"
var attribute = (vars.inputPayload.attributeSynchronization default [])[0] default {
}
---
{
	transactionId: vars.transactionId,
	createDate: vars.inputPayload.createDate,
	message: {
		billAttrObj: {
			id: attribute.billAttrObj.id,
			attrCode: attribute.billAttrObj.attrCode,
			attrName: attribute.billAttrObj.attrName,
			defaultValue: attribute.billAttrObj.defaultValue,
			inputType: attribute.billAttrObj.inputType,
			comments: attribute.billAttrObj.comments,
			operate: attribute.billAttrObj.operate
		},
		billAttrValueList: (attribute.billAttrValueList default []) map (attributeValue) -> {
			id: attributeValue.id,
			attrCode: attributeValue.attrCode,
			value: attributeValue.value,
			operate: attributeValue.operate
		}
	}
}

ee:variables.ee:set-variable:
%dw 2.0
output application/json
var requestHeaders = attributes.headers
---
{
	host: p('zsmart-sapi.host'),
	port: p('zsmart-sapi.port'),
	basepath: p('zsmart-sapi.base-path'),
	path: p('zsmart-sapi.attribute-sync.path'),
	method: p('zsmart-sapi.attribute-sync.post.method'),
	headers: {
		"client_secret": p('zsmart-sapi.security.client_secret'),
		"client_id": p('zsmart-sapi.security.client_id'),
		"name": requestHeaders.name,
		"X-CORRELATION-ID": requestHeaders."X-CORRELATION-ID",
		"source": requestHeaders.source,
		"systemId": requestHeaders.systemId
	},
	queryParameters: {
	},
	uriParameters: {
	},
	responseTimeout: p('configurationTimeout.zsmart-sapi.responseTimeout')
}

set-variable.value:
#[{
	responseCode: '9999',
	responseMessage: error.description default error.detailedDescription default 'Error processing attributeSynchronization'
}]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	transactionId: vars.transactionId,
	createDate: vars.inputPayload.createDate,
	message: {
		prodList: (vars.inputPayload.productSynchronization default []) map (product) -> {
			prodType: product.prodType,
			id: product.id,
			prodName: product.prodName,
			prodCode: product.prodCode,
			networkType: product.networkType,
			comments: product.comments,
			operate: product.operate,
			(productAttrList: (product.productAttrList default []) map (attribute) -> {
				id: attribute.id,
				productCode: attribute.productCode,
				attrCode: attribute.attrCode,
				defaultValue: attribute.defaultValue,
				operate: attribute.operate
			}) if (product.productAttrList?)
		}
	}
}

