ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn = "everywhere"
var synchronization = (vars.inputPayload.offerRelaSynchronization default [])[0] default {
}
---
{
	transactionId: vars.transactionId,
	createDate: vars.inputPayload.createDate,
	message: {
		(bundleMemberList: synchronization.bundleMemberList map (bundle) -> {
			bundleOfferCode: bundle.bundleOfferCode,
			bundleOfferName: bundle.bundleOfferName,
			memMainOfferCode: bundle.memMainOfferCode,
			memMainOfferName: bundle.memMainOfferName,
			operate: bundle.operate
		}) if (synchronization.bundleMemberList?),
		(mainOfferMemberList: synchronization.mainOfferMemberList map (offer) -> {
			mainOfferCode: offer.mainOfferCode,
			mainOfferName: offer.mainOfferName,
			memAddOfferCode: offer.memAddOfferCode,
			memAddOfferName: offer.memAddOfferName,
			operate: offer.operate
		}) if (synchronization.mainOfferMemberList?)
	}
}

