	headers: {
		"client_secret": p('zsmart-sapi.security.client_secret'),
		"client_id": p('zsmart-sapi.security.client_id'),
		"name": requestHeaders.name,
		"X-CORRELATION-ID": requestHeaders."X-CORRELATION-ID",
		"source": requestHeaders.source,
		"systemId": requestHeaders.systemId
	},
	queryParameters: {
	},
	uriParameters: {
	},
	responseTimeout: p('configurationTimeout.zsmart-sapi.responseTimeout')
}

set-variable.value:
#[{
	responseCode: '9999',
	responseMessage: error.description default error.detailedDescription default 'Error processing offerRelaSynchronization'
}]

set-payload.value:
#[%dw 2.0
output application/json
---
{
	transactionId: vars.transactionId,
	results: {
	} ++ (if ( vars.attributeSynchronizationResult? ) {
		attributeSynchronization: vars.attributeSynchronizationResult
	}
            else
                {
	}) ++ (if ( vars.productSynchronizationResult? ) {
		productSynchronization: vars.productSynchronizationResult
	}
            else
                {
	}) ++ (if ( vars.offerSynchronizationResult? ) {
		offerSynchronization: vars.offerSynchronizationResult
	}
            else
                {
	}) ++ (if ( vars.offerRelaSynchronizationResult? ) {
		offerRelaSynchronization: vars.offerRelaSynchronizationResult
	}
            else
                {
	})
}]
